shots.draw_js:
clearScene();setBig(null);setEq(null);
note("目标网络：两份权重",400,280,"b lg");
note("Double DQN：也两份",880,280,"v lg");
note("那它们差在哪",640,400,"y lg");
setCap("两个机制都用了<b>两份权重</b>，而且都和 max 有关。很容易混成一个。");

clearScene();setEq(null);
setBig("Double DQN 就是目标网络","都是两份权重，都在处理那个 max");
setCap("两者<b>都</b>解耦了「选动作」与「评动作」—— 但代价完全不同。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"目标网络",sub:"w⁻ 冻结 C 步",state:"on"},
  {label:"Double DQN",sub:"两份对称 · 可每步互换",state:"on"}]});
note("差别在「冻不冻」",640,420,"y");
setCap("目标网络的第二份是<b>过时的</b>；Double DQN 的第二份是<b>同样新的</b>。");

clearScene();setBig(null);setEq(null);
note("目标网络：等 C 步",400,290,"r lg");
note("Double：立刻可用",880,290,"g lg");
note("解耦的代价不同",640,400,"y lg");
setCap("目标网络用<b>信息延迟</b>换解耦；Double DQN <b>不付这个代价</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"目标网络",sub:"治目标非平稳",state:"on"},
  {label:"Double DQN",sub:"治最大化偏差",state:"on"},
  {label:"同时用",sub:"两个病不一样",state:"on"}]});
note("别记成同一件事",640,420,"y");
setCap("<b>指名反驳</b>：一个治<b>目标漂移</b>，一个治<b>偏差</b>。病不同，代价也不同。");

clearScene();setBig(null);
setEq("$$Q(s,a)=V(s)+A(s,a)$$","top");
note("两条流，合成一个 Q",640,300,"b lg");
note("网络只被 Q 监督",640,360,"r lg");
setCap("dueling 把头拆成 V 与 A 两路。<b>但训练信号只作用在合起来的 Q 上。</b>");

clearScene();setEq(null);
setBig("网络自己会学出来","反正 V 和 A 各有各的含义");
setCap("它<b>学不出来</b> —— 因为有无穷多组 (V, A) 给出同一个 Q。");

clearScene();setBig(null);
setEq("$$(V+c)+(A-c)=V+A=Q \\qquad \\forall c$$","top");
note("整条直线都给同一个 Q",640,310,"r lg");
setCap("不可辨识：<b>加一个常数再减掉</b>，Q 一个字节都不变。");

clearScene();setBig(null);
setEq("$$Q(s,a)=V(s)+A(s,a)-\\max_{a'}A(s,a')$$","top");
note("强制最优动作的 A = 0",640,300,"g lg");
note("直线上钉死一个点",640,360,"y lg");
setCap("解法是<b>定规范</b>：强制 <b>A(s, a*) = 0</b>，于是 V(s) 就等于 max_a Q(s,a)。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"不加约束",sub:"无穷多组 (V,A)",state:"dead"},
  {label:"减 max A",sub:"V = max Q，含义恢复",state:"on"},
  {label:"减均值 A",sub:"启发式 · 更稳",state:"on"}]});
note("这不是训练问题",640,420,"y");
setCap("<b>指名反驳</b>：不是网络学不好，是<b>没有唯一解可学</b> —— 必须人为定规范。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:290,items:[
  {label:"Double DQN",sub:"修偏差",state:"on"},
  {label:"优先回放",sub:"修效率",state:"on"},
  {label:"dueling",sub:"修数据利用",state:"on"},
  {label:"Montezuma",sub:"仍然不会玩",state:"dead"}]});
note("三个改动都没碰探索",640,430,"r");
setCap("Rainbow 把这些叠起来收益近似可加 —— <b>而 Montezuma 依然没被解决</b>。");

clearScene();setEq(null);
setBig("探索只是慢一点","ε 开大些、多跑几轮总能找到");
setCap("这在小的表格问题上成立。<b>而最坏情况下有下界，不是慢，是贵。</b>");

clearScene();setBig(null);setEq(null);
note("奖励",400,280,"y lg");
note("示范",880,280,"g lg");
note("两种监督信号",640,400,"ink lg");
setCap("于是问一个新问题：<b>除了奖励，还有什么能当监督？</b>");

clearScene();setBig(null);setEq(null);
note("状态空间 · 动作空间",400,270,"g lg","start");
note("转移 · 奖励函数",400,340,"r lg","start");
note("专家轨迹",400,410,"g lg","start");
setCap("示范学习的设定：<b>有</b>状态动作空间与专家轨迹，<b>没有</b>转移和奖励。");

clearScene();setBig(null);setEq(null);
note("探索：自己撞出好行为",400,290,"r lg");
note("示范：好行为已在数据里",880,290,"g lg");
note("换掉的是监督来源",640,400,"y lg");
setCap("<b>指名反驳</b>：探索不是「慢一点」，它有下界。示范换掉的是<b>监督的来源</b>。");
